    },
    methods:{
      submitPayment(){
        this.showLoading = true
        payOrder({
          redirect_url: 'https://codropshipping.com/admin/account/storePaymentResult',
          order_number: this.list.order_number,
          payment_method: this.payment_method, 
        }).then((res) => {
          this.showLoading = false
          if(res.code=='-1'){
            this.$message({
              message: res.msg,
              offset: 70
            });
          }else if(res.code==0){
            window.open(res.data.url,"_self")
          }
        })
      }
    }
  }
</script>

<style lang="postcss" scoped>
  .btn{
    @apply h-12 w-48 bg-black hover:bg-gray-500 text-white rounded text-base;
  }
</style>